119	        self.elements.position(location).copied().map(DocumentPosition::Paged)
120	    }
121	
122	    fn page_numbering(&self, location: Location) -> Option<&Numbering> {
123	        let page = self.page(location)?;
124	        self.page_numberings.get(page.get() - 1)?.as_ref()
125	    }
126	
127	    fn page_supplement(&self, location: Location) -> Option<&Content> {
128	        let page = self.page(location)?;
129	        self.page_supplements.get(page.get() - 1)
130	    }
131	
132	    fn anchor(&self, _: Location) -> Option<&EcoString> {
133	        None
134	    }
135	
136	    fn document(&self, _: Location) -> Option<Location> {
137	        None
138	    }
139	
140	    fn path(&self, _: Location) -> Option<&VirtualPath> {
141	        None
142	    }
143	}
