167	        world: Tracked<dyn World + '_>,
168	        introspectors: [&dyn Introspector; INSTANCES],
169	    ) -> Option<SourceDiagnostic>;
170	    fn dyn_eq(&self, other: &Introspection) -> bool;
171	    fn dyn_hash(&self, state: &mut dyn Hasher);
172	}
