258	    pub fn as_ref(&self) -> History<'a, &T> {
259	        History(self.0.each_ref().map(|(i, t)| (*i, t)))
260	    }
261	
262	    /// Accesses the final iteration's introspector.
263	    pub fn final_introspector(&self) -> &'a dyn Introspector {
264	        self.0[MAX_ITERS].0
265	    }
