734	impl ManualPageCounter {
735	    /// Create a new fast page counter, starting at 1.
736	    pub fn new() -> Self {
737	        Self { physical: NonZeroUsize::ONE, logical: 1 }
738	    }
739	
740	    /// Get the current physical page counter state.
741	    pub fn physical(&self) -> NonZeroUsize {
