96	/// A finished page.
97	#[derive(Debug, Clone, Hash)]
98	pub struct Page {
99	    /// The frame that defines the page.
100	    pub frame: Frame,
101	    /// The bleed amount to be added on each side of the page. The bleed is not
102	    /// included in frame.
103	    pub bleed: Sides<Abs>,
104	    /// How the page is filled.
105	    ///
106	    /// - When `None`, the background is transparent.
107	    /// - When `Auto`, the background is transparent for PDF and white
108	    ///   for raster and SVG targets.
109	    ///
110	    /// Exporters should access the resolved value of this property through
111	    /// `fill_or_transparent()` or `fill_or_white()`.
112	    pub fill: Smart<Option<Paint>>,
113	    /// The page's numbering.
114	    pub numbering: Option<Numbering>,
115	    /// The page's supplement.
116	    pub supplement: Content,
117	    /// The logical page number (controlled by `counter(page)` and may thus not
118	    /// match the physical number).
119	    pub number: u64,
120	}
121	
122	impl Page {
123	    /// Get the configured background or `None` if it is `Auto`.
124	    ///
125	    /// This is used in PDF export.
126	    pub fn fill_or_transparent(&self) -> Option<Paint> {
127	        self.fill.clone().unwrap_or(None)
128	    }
129	
130	    /// Get the configured background or white if it is `Auto`.
131	    ///
132	    /// This is used in raster and SVG export.
133	    pub fn fill_or_white(&self) -> Option<Paint> {
134	        self.fill.clone().unwrap_or_else(|| Some(Color::WHITE.into()))
135	    }
136	}
