use typst::syntax::{
    FileId, RangeMapper, RootedPath, Source, Span, SyntaxMode, VirtualPath, VirtualRoot,
};
use typst::text::{Font, FontBook};
use typst::{World, engine::Sink, introspection::Introspector};
use typst_bundle::Bundle;
use typst_eval::eval_string;
use typst_html::HtmlDocument;
use typst_kit::diagnostics::DiagnosticWorld;
use typst_layout::PagedDocument;
use typst_utils::LazyHash;

use crate::args::{
    self, EvalCommand, EvalSerializationFormat, SerializationFormat, Target,
};
use crate::compile::print_diagnostics;
use crate::set_failed;
use crate::world::SystemWorld;

/// Evaluate an input expression, potentially as a query over an existing
/// document.
pub fn eval(command: &'static EvalCommand) -> HintedStrResult<()> {
    let output_format = if let Some(specified) = command.format {
        specified
    } else if let args::Output::Path(output) = &command.output {
        match output.extension() {
            Some(ext) if ext.eq_ignore_ascii_case("json") => {
                EvalSerializationFormat::Json
            }
            Some(ext)
                if ext.eq_ignore_ascii_case("yaml")
                    || ext.eq_ignore_ascii_case("yml") =>
            {
                EvalSerializationFormat::Yaml
            }
            _ => bail!(
                "could not infer output format for path {}.\n\
                 consider providing the format manually with `--format/-f`",
                output.display(),
            ),
        }
    } else {
        EvalSerializationFormat::default()
    };

    let mut world =
        SystemWorld::new(command.r#in.as_ref(), &command.world, &command.process)?;

    // Reset everything and ensure that the main file is present.
    world.reset();
    world.source(world.main()).map_err(|err| err.to_string())?;

    // Compile the main file and get the introspector.
    let Warned { output, mut warnings } = match command.target {
        Target::Paged => typst::compile::<PagedDocument>(&world)
            .map(|output| Box::new(output) as Box<dyn Output>),
        Target::Html => typst::compile::<HtmlDocument>(&world)
            .map(|output| Box::new(output) as Box<dyn Output>),
        Target::Bundle => typst::compile::<Bundle>(&world)
            .map(|output| Box::new(output) as Box<dyn Output>),
    };

    match output {
        // The target compiled successfully, continue with evaluating the input
        // expression.
        Ok(output) => {
            let expr_world = ExpressionWorld {
                world,
                expression: Bytes::from_string(&*command.expression),
            };
            let mut sink = Sink::new();
            let eval_result = evaluate_expression(
                &command.expression,
                &mut sink,
                &expr_world,
                output.introspector(),
            );
            let errors = match &eval_result {
                Err(errors) => {
                    set_failed();
                    errors.as_slice()
                }
                Ok(value) => {
                    print_eval_result(
                        value,
                        &command.output,
                        output_format,
                        command.pretty,
                    )?;
                    &[]
                }
            };
            // Collect additional warnings from evaluating the expression.
            warnings.extend(sink.warnings());

            print_diagnostics(
                &expr_world,
                errors,
                &warnings,
                command.process.diagnostic_format,
            )
            .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
        }

        // The target failed, print its diagnostics.
        Err(errors) => {
            set_failed();
            print_diagnostics(
                &world,
                &errors,
                &warnings,
                command.process.diagnostic_format,
            )
            .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
        }
    }

    Ok(())
}

/// Evaluate the input expression in [`SyntaxMode::Code`] and with no scope.
fn evaluate_expression(
    expression: &str,
    sink: &mut Sink,
    world: &dyn World,
    introspector: &dyn Introspector,
) -> SourceResult<Value> {
    // Map spans to ranges in the string.
    let spans = SpanMode::Mapped {
        id: *EXPRESSION_ID,
        mapper: &RangeMapper::new(Some(0..expression.len())).unwrap(),
        mapper_error_span: Span::detached(),
    };
    let library = world.library();
    eval_string(
        world.track(),
        library,
        sink.track_mut(),
        introspector.track(),
        Context::new(None, Some(StyleChain::new(&library.styles))).track(),
        expression,
        spans,
        SyntaxMode::Code,
        Scope::default(),
    )
}

/// Prints the output value of `typst eval`.
fn print_eval_result(
    value: &Value,
    output: &args::Output,
    format: EvalSerializationFormat,
    pretty: bool,
) -> HintedStrResult<()> {
    let format = match format {
        EvalSerializationFormat::Json => Some(SerializationFormat::Json),
        EvalSerializationFormat::Yaml => Some(SerializationFormat::Yaml),
        EvalSerializationFormat::Raw => None,
    };
    let result = match format {
        Some(format) => {
            let mut serialized = crate::serialize(&value, format, pretty)?;
            if !serialized.ends_with('\n') {
                serialized.push('\n');
            }
            output.write(serialized.as_bytes())
        }
        None => {
            let bytes = match value {
                Value::Str(string) => string.as_bytes(),
                Value::Bytes(bytes) => bytes,
                _ => bail!(
                    "cannot print {} in raw format", value.ty();
                    hint: "`--format=raw` only supports strings and bytes"
                ),
            };
            output.write(bytes)
        }
    };
    result.map_err(|err| eco_format!("failed to write eval output ({err})").into())
}

/// Static [`FileId`] for an input expression. This allows giving accurate
/// ranges to diagnostics when evaluating the expression.
static EXPRESSION_ID: LazyLock<FileId> = LazyLock::new(|| {
    FileId::unique(RootedPath::new(
        VirtualRoot::Project,
        VirtualPath::new("<input-expression>").unwrap(),
    ))
});

/// A world wrapper that allows us to print accurate diagnostics for an input
/// expression.
struct ExpressionWorld {
    world: SystemWorld,
    /// We use `Bytes`, not `&'static str` to avoid hashing in `World::file`.
    expression: Bytes,
}

impl DiagnosticWorld for ExpressionWorld {
    fn name(&self, id: FileId) -> String {
        if id == *EXPRESSION_ID {
            "<input-expression>".into()
        } else {
            self.world.name(id)
        }
    }
}

impl World for ExpressionWorld {
    fn library(&self) -> &LazyHash<Library> {
        self.world.library()
    }

    fn book(&self) -> &LazyHash<FontBook> {
        self.world.book()
    }

    fn main(&self) -> FileId {
        self.world.main()
    }

    fn source(&self, id: FileId) -> FileResult<Source> {
        self.world.source(id)
    }

    fn file(&self, id: FileId) -> FileResult<Bytes> {
        if id == *EXPRESSION_ID {
            Ok(self.expression.clone())
        } else {
            self.world.file(id)
        }
    }

    fn font(&self, index: usize) -> Option<Font> {
        self.world.font(index)
    }

    fn today(&self, offset: Option<Duration>) -> Option<Datetime> {
        self.world.today(offset)
    }
}

